DELETE FROM ai_project_panorama_snapshot
WHERE panorama_snapshot_id = #{panoramaSnapshotId}
  AND expires_at <= CURRENT_TIMESTAMP
  AND NOT EXISTS (
      SELECT 1
      FROM ai_project_panorama_snapshot_module module_ref
      WHERE module_ref.panorama_snapshot_id = #{panoramaSnapshotId}
  )
